lab.solution:
def response_action(status_code):
    if status_code == 200:
        return 'use response'
    if status_code == 429:
        return 'wait according to server guidance'
    if 500 <= status_code <= 599:
        return 'consider bounded retry for a safe operation'
    return 'show a clear error; do not guess'

for code in [200, 404, 429, 503]:
    print(code, response_action(code))
